import { create } from 'zustand';
import { devtools } from 'zustand/middleware';

export type DataMode = 'pesticide_total' | 'pfas' | 'diquat' | 'glyphosate';

export interface MapState {
  // Map view state
  zoom: number;
  center: [number, number];
  bearing: number;
  pitch: number;
  
  // Data selection
  selectedYear: number;
  selectedDataMode: DataMode;
  selectedH3Resolution: number;
  
  // Layer visibility
  showKommuneLayer: boolean;
  showH3Layer: boolean;
  showBNBOLayer: boolean;
  showBasemap: boolean;
  
  // Loading states
  isLoading: boolean;
  isLoadingYear: boolean;
  isLoadingTiles: boolean;
  loadingMessage: string;
  
  // Error states
  error: string | null;
  
  // Data availability
  availableYears: number[];
  availableResolutions: number[];
  
  // UI state
  showControls: boolean;
  showTooltip: boolean;
  tooltipData: any;
  tooltipPosition: { x: number; y: number };
  
  // Computed properties
  shouldShowKommune: boolean;
  shouldShowH3: boolean;
  currentH3Resolution: number;
}

export interface MapActions {
  // Map view actions
  setZoom: (zoom: number) => void;
  setCenter: (center: [number, number]) => void;
  setBearing: (bearing: number) => void;
  setPitch: (pitch: number) => void;
  setViewState: (viewState: Partial<Pick<MapState, 'zoom' | 'center' | 'bearing' | 'pitch'>>) => void;
  
  // Data selection actions
  setSelectedYear: (year: number) => void;
  setSelectedDataMode: (mode: DataMode) => void;
  setSelectedH3Resolution: (resolution: number) => void;
  
  // Layer visibility actions
  setShowKommuneLayer: (show: boolean) => void;
  setShowH3Layer: (show: boolean) => void;
  setShowBNBOLayer: (show: boolean) => void;
  setShowBasemap: (show: boolean) => void;
  toggleBNBOLayer: () => void;
  
  // Loading state actions
  setIsLoading: (loading: boolean) => void;
  setIsLoadingYear: (loading: boolean) => void;
  setIsLoadingTiles: (loading: boolean) => void;
  setLoadingMessage: (message: string) => void;
  
  // Error state actions
  setError: (error: string | null) => void;
  clearError: () => void;
  
  // Data availability actions
  setAvailableYears: (years: number[]) => void;
  setAvailableResolutions: (resolutions: number[]) => void;
  
  // UI actions
  setShowControls: (show: boolean) => void;
  setShowTooltip: (show: boolean) => void;
  setTooltipData: (data: any) => void;
  setTooltipPosition: (position: { x: number; y: number }) => void;
  showTooltipWithData: (data: any, position: { x: number; y: number }) => void;
  hideTooltip: () => void;
  
  // Utility actions
  resetToDefaults: () => void;
  updateComputedProperties: () => void;
}

const DEFAULT_CENTER: [number, number] = [10.0, 56.0]; // Center of Denmark
const DEFAULT_ZOOM = 7;
const DEFAULT_YEAR = 2023;
const DEFAULT_DATA_MODE: DataMode = 'pesticide_total';

// Zoom thresholds for layer switching
const KOMMUNE_MAX_ZOOM = 8;
const H3_MIN_ZOOM = 9;

// H3 resolution based on zoom level
const getH3ResolutionForZoom = (zoom: number): number => {
  if (zoom >= 14) return 10;
  if (zoom >= 12) return 9;
  if (zoom >= 10) return 8;
  return 7;
};

export const useMapStore = create<MapState & MapActions>()(
  devtools(
    (set, get) => ({
      // Initial state
      zoom: DEFAULT_ZOOM,
      center: DEFAULT_CENTER,
      bearing: 0,
      pitch: 0,
      
      selectedYear: DEFAULT_YEAR,
      selectedDataMode: DEFAULT_DATA_MODE,
      selectedH3Resolution: 7,
      
      showKommuneLayer: true,
      showH3Layer: false,
      showBNBOLayer: false,
      showBasemap: true,
      
      isLoading: false,
      isLoadingYear: false,
      isLoadingTiles: false,
      loadingMessage: '',
      
      error: null,
      
      availableYears: [],
      availableResolutions: [7, 8, 9, 10],
      
      showControls: true,
      showTooltip: false,
      tooltipData: null,
      tooltipPosition: { x: 0, y: 0 },
      
      // Computed properties
      shouldShowKommune: true,
      shouldShowH3: false,
      currentH3Resolution: 7,
      
      // Map view actions
      setZoom: (zoom) => {
        set((state) => {
          const newState = { ...state, zoom };
          return updateComputedPropertiesInternal(newState);
        });
      },
      
      setCenter: (center) => set({ center }),
      setBearing: (bearing) => set({ bearing }),
      setPitch: (pitch) => set({ pitch }),
      
      setViewState: (viewState) => {
        set((state) => {
          const newState = { ...state, ...viewState };
          return updateComputedPropertiesInternal(newState);
        });
      },
      
      // Data selection actions
      setSelectedYear: (selectedYear) => {
        set({ selectedYear, isLoadingYear: true });
      },
      
      setSelectedDataMode: (selectedDataMode) => {
        set({ selectedDataMode });
      },
      
      setSelectedH3Resolution: (selectedH3Resolution) => {
        set({ selectedH3Resolution });
      },
      
      // Layer visibility actions
      setShowKommuneLayer: (showKommuneLayer) => set({ showKommuneLayer }),
      setShowH3Layer: (showH3Layer) => set({ showH3Layer }),
      setShowBNBOLayer: (showBNBOLayer) => set({ showBNBOLayer }),
      setShowBasemap: (showBasemap) => set({ showBasemap }),
      
      toggleBNBOLayer: () => {
        set((state) => ({ showBNBOLayer: !state.showBNBOLayer }));
      },
      
      // Loading state actions
      setIsLoading: (isLoading) => set({ isLoading }),
      setIsLoadingYear: (isLoadingYear) => set({ isLoadingYear }),
      setIsLoadingTiles: (isLoadingTiles) => set({ isLoadingTiles }),
      setLoadingMessage: (loadingMessage) => set({ loadingMessage }),
      
      // Error state actions
      setError: (error) => set({ error }),
      clearError: () => set({ error: null }),
      
      // Data availability actions
      setAvailableYears: (availableYears) => set({ availableYears }),
      setAvailableResolutions: (availableResolutions) => set({ availableResolutions }),
      
      // UI actions
      setShowControls: (showControls) => set({ showControls }),
      setShowTooltip: (showTooltip) => set({ showTooltip }),
      setTooltipData: (tooltipData) => set({ tooltipData }),
      setTooltipPosition: (tooltipPosition) => set({ tooltipPosition }),
      
      showTooltipWithData: (data, position) => {
        set({
          showTooltip: true,
          tooltipData: data,
          tooltipPosition: position,
        });
      },
      
      hideTooltip: () => {
        set({
          showTooltip: false,
          tooltipData: null,
        });
      },
      
      // Utility actions
      resetToDefaults: () => {
        set((state) => {
          const newState = {
            ...state,
            zoom: DEFAULT_ZOOM,
            center: DEFAULT_CENTER,
            bearing: 0,
            pitch: 0,
            selectedYear: DEFAULT_YEAR,
            selectedDataMode: DEFAULT_DATA_MODE,
            selectedH3Resolution: 7,
            showKommuneLayer: true,
            showH3Layer: false,
            showBNBOLayer: false,
            showBasemap: true,
            isLoading: false,
            isLoadingYear: false,
            isLoadingTiles: false,
            loadingMessage: '',
            error: null,
            showControls: true,
            showTooltip: false,
            tooltipData: null,
            tooltipPosition: { x: 0, y: 0 },
          };
          return updateComputedPropertiesInternal(newState);
        });
      },
      
      updateComputedProperties: () => {
        set((state) => updateComputedPropertiesInternal(state));
      },
    }),
    {
      name: 'map-store',
      partialize: (state: MapState & MapActions) => ({
        // Persist only essential state
        zoom: state.zoom,
        center: state.center,
        selectedYear: state.selectedYear,
        selectedDataMode: state.selectedDataMode,
        showBNBOLayer: state.showBNBOLayer,
        showControls: state.showControls,
      }),
    }
  )
);

// Helper function to update computed properties
function updateComputedPropertiesInternal(state: MapState): MapState {
  const shouldShowKommune = state.zoom <= KOMMUNE_MAX_ZOOM;
  const shouldShowH3 = state.zoom >= H3_MIN_ZOOM;
  const currentH3Resolution = getH3ResolutionForZoom(state.zoom);
  
  return {
    ...state,
    shouldShowKommune,
    shouldShowH3,
    currentH3Resolution,
    // Auto-update layer visibility based on zoom
    showKommuneLayer: shouldShowKommune,
    showH3Layer: shouldShowH3,
    selectedH3Resolution: currentH3Resolution,
  };
}

