'use client'

import React, { useEffect, useRef, useState } from 'react'
import { ErrorBoundary } from 'react-error-boundary'
import { MapTooltip } from './MapTooltip'
import { useMapStore, useMapViewState, useDataState, useLayerVisibility, useLoadingState } from '@/stores/map-store'

// Dynamic imports for browser-only modules
const loadMapLibreAndPMTiles = async () => {
  if (typeof window === 'undefined') return null
  
  const [maplibregl, { Protocol }] = await Promise.all([
    import('maplibre-gl'),
    import('pmtiles')
  ])
  
  // Register PMTiles protocol
  let protocolRegistered = false
  if (!protocolRegistered) {
    const protocol = new Protocol()
    maplibregl.default.addProtocol('pmtiles', protocol.tile)
    protocolRegistered = true
  }
  
  return maplibregl.default
}

interface PMTilesMapProps {
  className?: string
}

const PMTilesMapInner: React.FC<PMTilesMapProps> = ({ className = 'w-full h-full' }) => {
  const mapContainer = useRef<HTMLDivElement>(null)
  const map = useRef<any>(null)
  const [mapLibre, setMapLibre] = useState<any>(null)
  const [mapLoaded, setMapLoaded] = useState(false)
  
  // Store state
  const { zoom, center, bearing, pitch } = useMapViewState()
  const { selectedYear, selectedDataMode } = useDataState()
  const { showBNBOLayer } = useLayerVisibility()
  const { isLoading, error } = useLoadingState()
  
  // Store actions
  const { 
    setViewState,
    setIsLoading,
    setError, 
    clearError,
    showTooltipWithData,
    hideTooltip,
    updateComputedProperties
  } = useMapStore()

  // Load MapLibre and PMTiles
  useEffect(() => {
    loadMapLibreAndPMTiles().then(setMapLibre)
  }, [])

  // Initialize map
  useEffect(() => {
    if (!mapContainer.current || map.current || !mapLibre) return

    try {
      map.current = new mapLibre.Map({
        container: mapContainer.current,
        style: {
          version: 8,
          sources: {
            'basemap': {
              type: 'raster',
              tiles: [
                'https://tile.openstreetmap.org/{z}/{x}/{y}.png'
              ],
              tileSize: 256,
              attribution: '© OpenStreetMap contributors'
            }
          },
          layers: [
            {
              id: 'basemap',
              type: 'raster',
              source: 'basemap',
              paint: {
                'raster-opacity': 0.8
              }
            }
          ],
        },
        center: center,
        zoom: zoom,
        bearing: bearing,
        pitch: pitch,
        maxZoom: 15,
        minZoom: 4,
        maxBounds: [
          [7.0, 54.0], // Southwest bounds (Denmark)
          [13.0, 58.0], // Northeast bounds (Denmark)
        ],
      })

      // Add controls
      map.current.addControl(new mapLibre.NavigationControl(), 'top-right')
      map.current.addControl(new mapLibre.ScaleControl(), 'bottom-left')

      // Map event handlers
      map.current.on('load', () => {
        setMapLoaded(true)
        updateComputedProperties()
        clearError()
      })

      map.current.on('move', () => {
        if (!map.current) return
        const { lng, lat } = map.current.getCenter()
        const zoom = map.current.getZoom()
        const bearing = map.current.getBearing()
        const pitch = map.current.getPitch()
        
        setViewState({ 
          center: [lng, lat], 
          zoom, 
          bearing, 
          pitch 
        })
      })

      map.current.on('click', (e: any) => {
        const features = map.current?.queryRenderedFeatures(e.point)
        if (features && features.length > 0) {
          const feature = features[0]
          showTooltipWithData(feature.properties, { x: e.point.x, y: e.point.y })
        } else {
          hideTooltip()
        }
      })

      map.current.on('mousemove', (e: any) => {
        const features = map.current?.queryRenderedFeatures(e.point)
        if (features && features.length > 0) {
          const feature = features[0]
          showTooltipWithData(feature.properties, { x: e.point.x, y: e.point.y })
          if (map.current) {
            map.current.getCanvas().style.cursor = 'pointer'
          }
        } else {
          hideTooltip()
          if (map.current) {
            map.current.getCanvas().style.cursor = ''
          }
        }
      })

      map.current.on('mouseleave', () => {
        hideTooltip()
        if (map.current) {
          map.current.getCanvas().style.cursor = ''
        }
      })

      map.current.on('error', (e: any) => {
        console.error('Map error:', e)
        setError('Map loading error')
      })

    } catch (err) {
      console.error('Error initializing map:', err)
      setError('Failed to initialize map')
    }

    return () => {
      if (map.current) {
        map.current.remove()
        map.current = null
      }
    }
  }, [mapLibre, center, zoom, bearing, pitch])

  // Show loading state
  if (!mapLibre || isLoading) {
    return (
      <div className={`relative flex items-center justify-center bg-gray-900 ${className}`}>
        <div className="text-center">
          <div className="w-8 h-8 border-2 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-white text-sm">Loading map...</p>
        </div>
      </div>
    )
  }

  // Show error state
  if (error) {
    return (
      <div className={`relative flex items-center justify-center bg-gray-900 ${className}`}>
        <div className="text-center">
          <div className="text-red-400 text-4xl mb-4">⚠️</div>
          <p className="text-white text-sm mb-2">Map Error</p>
          <p className="text-gray-400 text-xs">{error}</p>
          <button
            onClick={clearError}
            className="mt-4 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded transition-colors"
          >
            Retry
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className={`relative ${className}`}>
      <div ref={mapContainer} className="w-full h-full" />
      
      {/* Loading overlay */}
      {!mapLoaded && (
        <div className="absolute inset-0 flex items-center justify-center bg-gray-900/80">
          <div className="text-center">
            <div className="w-6 h-6 border-2 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto mb-2"></div>
            <p className="text-white text-sm">Initializing map...</p>
          </div>
        </div>
      )}
      
      {/* Map info overlay */}
      <div className="absolute top-4 left-4 bg-black/80 text-white px-3 py-2 rounded text-sm">
        <div>Year: {selectedYear}</div>
        <div>Mode: {selectedDataMode}</div>
        <div>Zoom: {Math.round(zoom * 10) / 10}</div>
      </div>
      
      {/* Tooltip */}
      <MapTooltip />
    </div>
  )
}

// Error boundary component
const MapErrorFallback: React.FC<{ error: Error; resetErrorBoundary: () => void }> = ({ 
  error, 
  resetErrorBoundary 
}) => (
  <div className="flex items-center justify-center h-full bg-gray-900">
    <div className="text-center">
      <div className="text-red-400 text-6xl mb-4">⚠️</div>
      <h2 className="text-white text-xl font-semibold mb-2">Map Error</h2>
      <p className="text-gray-400 mb-4">{error.message}</p>
      <button
        onClick={resetErrorBoundary}
        className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg transition-colors"
      >
        Reload Map
      </button>
    </div>
  </div>
)

// Main exported component with error boundary
export const PMTilesMap: React.FC<PMTilesMapProps> = (props) => {
  return (
    <ErrorBoundary FallbackComponent={MapErrorFallback}>
      <PMTilesMapInner {...props} />
    </ErrorBoundary>
  )
}